pub fn _json_put_bool(v: *JsonValue, key: []const u8, val: bool) void {
    if (v.* != .object) return;
    v.object.put(std.heap.page_allocator, std.heap.page_allocator.dupe(u8, key) catch return, .{ .bool = val }) catch {};
