// `query` is the RAW text after the first '?', empty when there is none. It is not
// decoded here: percent-decoding is the caller's business, and doing it in the parser
// would make `a=1&b=%26` ambiguous by turning an escaped separator into a real one.
pub const HttpRequest = struct { method: []const u8, path: []const u8, content: []const u8, query: []const u8 = "" };
pub fn _http_serve(port: u16, handler: anytype) void {
    const _HFn = *const fn(HttpRequest) HttpResponse;
    const _fn: _HFn = handler;
    const _Ctx = struct {
        conn: std.Io.net.Stream,
        handler_fn: _HFn,
        fn run(ctx: *@This()) void {
            defer std.heap.page_allocator.destroy(ctx);
            defer ctx.conn.close(_io);
            const _alloc = std.heap.page_allocator;
            var _srv_rbuf: [4096]u8 = undefined;
            var _srv_rd = ctx.conn.reader(_io, &_srv_rbuf);
            // Read request headers byte-by-byte until \r\n\r\n.
            var _hd: [16384]u8 = undefined;
            var _hl: usize = 0;
            while (_hl < _hd.len - 1) {
                const _b = _srv_rd.interface.takeByte() catch break;
                _hd[_hl] = _b;
                _hl += 1;
                if (_hl >= 4 and _hd[_hl-4] == '\r' and _hd[_hl-3] == '\n' and _hd[_hl-2] == '\r' and _hd[_hl-1] == '\n') break;
            }
            const _head = _hd[0.._hl];
            // Parse request line: METHOD PATH VERSION
            const _rl_end = std.mem.indexOf(u8, _head, "\r\n") orelse _hl;
            var _rp = std.mem.splitScalar(u8, _head[0.._rl_end], ' ');
            const _method = _rp.next() orelse "GET";
            const _raw_path = _rp.next() orelse "/";
            // Split ONCE at the first '?' and keep BOTH halves. This used to cut the
            // path and discard the remainder, so a handler could not reach `?q=` at all
            // -- which is why callers reached for `/search/{q}` path-param stand-ins.
            const _q_at = std.mem.indexOfScalar(u8, _raw_path, '?');
            const _path = if (_q_at) |_qi| _raw_path[0.._qi] else _raw_path;
            const _query = if (_q_at) |_qi| _raw_path[_qi + 1 ..] else "";
            // Parse Content-Length.
            var _cl: usize = 0;
            var _hdr_it = std.mem.splitSequence(u8, _head, "\r\n");
            _ = _hdr_it.next();
            while (_hdr_it.next()) |_hl_| {
                if (_hl_.len == 0) break;
                const _cp = std.mem.indexOfScalar(u8, _hl_, ':') orelse continue;
                const _hn = std.mem.trim(u8, _hl_[0.._cp], " ");
                const _hv = std.mem.trim(u8, _hl_[_cp+1..], " ");
                if (std.ascii.eqlIgnoreCase(_hn, "content-length"))
                    _cl = std.fmt.parseInt(usize, _hv, 10) catch 0;
            }
            var _body: []const u8 = "";
            if (_cl > 0) {
                const _bb = _alloc.alloc(u8, _cl) catch @panic("OOM");
                var _bi: usize = 0;
                while (_bi < _cl) {
                    var _slices: [1][]u8 = .{_bb[_bi..]};
                    const _rn = _srv_rd.interface.readVec(&_slices) catch break;
                    if (_rn == 0) break;
                    _bi += _rn;
                }
                _body = _bb[0.._bi];
            }
            const _req = HttpRequest{ .method = _method, .path = _path, .content = _body, .query = _query };
